		telemetry.registration.installing !== null ||
		telemetry.registration.waiting !== null ||
		telemetry.registration.active !== null ||
		telemetry.controller !== null ||
		telemetry.cacheNames.length !== 0 ||
		telemetry.cacheEntries.length !== 0 ||
