			method: 'GET',
			path: '/assets/transparent.gif',
			reason: 'net::ERR_ABORTED',
		}),
	]),
	migrated: Object.freeze([
		Object.freeze({
			method: 'GET',
			path: '/assets/transparent.gif',
			reason: 'net::ERR_ABORTED',
