98	/**
99	 * Byte mutation on the migrated build: locate the visible columns-dialog title
100	 * in the served module, overwrite it in place with an equal-length filler,
101	 * require the journey to go red on that exact assertion, restore the original
102	 * bytes, and require the restored journey to reproduce the parity behavior
103	 * digest.
104	 */
105	async function semanticMutation(
106		laneRoot: string,
107		behaviorDigest: string,
108	): Promise<WitnessAngularFactoriolabMutation> {
109		const expected = Buffer.from(FACTORIOLAB_MUTATION_SEAM);
110		const candidates: Array<{ path: string; offset: number }> = [];
111		for (const path of await files(laneRoot)) {
112			const bytes = await readFile(path);
113			const offset = bytes.indexOf(expected);
114			if (offset < 0) continue;
115			if (bytes.lastIndexOf(expected) !== offset)
116				throw new Error('factoriolab semantic seam is not unique within its file');
117			candidates.push({ path, offset });
118		}
119		const target = candidates[0];
120		if (candidates.length !== 1 || target === undefined || !target.path.endsWith('.js'))
121			throw new Error('factoriolab semantic seam is not a single served module');
122		const before = await readFile(target.path);
123		const mutated = Buffer.from(before);
124		Buffer.alloc(expected.length, 'X').copy(mutated, target.offset);
125		const beforeSha256 = sha256(before);
126		const mutatedSha256 = sha256(mutated);
127		let intendedFailure = false;
128		try {
129			await writeFile(target.path, mutated);
130			try {
131				await executeAngularFactoriolabWitnessRun({
132					lane: 'migrated',
133					pass: 1,
134					laneRoot,
135					receiptRoot: join(stageRoot, 'mutation-receipt'),
136				});
137			} catch (error) {
138				const message = error instanceof Error ? error.message : String(error);
139				intendedFailure = message.includes(FACTORIOLAB_MUTATION_SEAM);
140			}
141		} finally {
142			await writeFile(target.path, before);
143		}
144		const afterRestoreSha256 = sha256(await readFile(target.path));
145		if (!intendedFailure || afterRestoreSha256 !== beforeSha256)
146			throw new Error('factoriolab semantic mutation was not exact red and byte-restored');
147		const restored = (await executeAngularFactoriolabWitnessRun({
148			lane: 'migrated',
149			pass: 1,
150			laneRoot,
151			receiptRoot: join(stageRoot, 'restoration-receipt'),
152		})) as WitnessAngularFactoriolabRun;
153		const restoredBehaviorDigest = witnessAngularFactoriolabBehaviorDigest(restored);
154		if (restoredBehaviorDigest !== behaviorDigest)
155			throw new Error('factoriolab restored browser behavior differs');
156		return {
157			failure: 'witness-semantic-assertion',
158			intendedFailure: true,
159			lane: 'migrated',
160			seam: FACTORIOLAB_MUTATION_SEAM,
161			path: relative(laneRoot, target.path),
162			offset: target.offset,
163			beforeSha256,
164			mutatedSha256,
165			afterRestoreSha256,
166			restoredByteIdentically: true,
167			restoredRun: 'pass',
168			restoredBehaviorDigest,
169		};
170	}
