198	export async function runWitnessAngularFactoriolab(): Promise<WitnessAngularFactoriolabReceipt> {
199		if (
200			process.env.VERSIONLESS_NETWORK_MODE !== 'offline' ||
201			process.env.NPM_CONFIG_OFFLINE !== 'true'
