242			buildLanes: {
243				baseline: {
244					angular: 'Angular 10.1',
245					builder: '@angular-devkit/build-angular:browser',
246					node: 'node 12.14.1 (darwin-x64 under Rosetta 2)',
247					distFiles: laneFileCounts.baseline,
248				},
249				migrated: {
250					angular: 'Angular 16.2',
251					builder: '@angular-devkit/build-angular:browser',
252					node: 'node 16.20.2 (darwin-arm64, native)',
253					distFiles: laneFileCounts.migrated,
254				},
255			},
256			persistence: {
257				plan: 'url-fragment-encoded',
258				preferences: 'browser-local-storage',
259				backend: 'none',
260				stubbed: false,
