281				'Receipts prove reproducibility and hash integrity, not certification, authenticity, signer identity, compliance, or an earned SLSA level.',
282			],
283			integrity: { algorithm: 'sha256', canonicalDigest: '' },
284		};
285		receipt.integrity.canonicalDigest = witnessAngularFactoriolabDigest(receipt);
286		parseWitnessAngularFactoriolabReceipt(receipt);
287		await mkdir(witnessEvidence, { recursive: true });
288		await writeFile(join(witnessEvidence, 'receipt.json'), `${canonicalize(receipt)}\n`, {
289			flag: 'wx',
290		});
291		await writeFile(
292			join(witnessEvidence, 'receipt.md'),
293			renderWitnessAngularFactoriolabReceipt(receipt),
294			{ flag: 'wx' },
295		);
296		return receipt;
297	}
298	
299	export async function verifyWitnessAngularFactoriolab(
300		output = witnessEvidence,
301	): Promise<WitnessAngularFactoriolabReceipt> {
302		const expectedProvenance = await verifyLinkedWitnessProvenance(root);
303		const receipt = parseWitnessAngularFactoriolabReceipt(
304			JSON.parse(await readFile(join(output, 'receipt.json'), 'utf8')),
305		);
306		if (canonicalize(receipt.provenance) !== canonicalize(expectedProvenance))
307			throw new Error('factoriolab linked Witness provenance differs');
308		for (const bound of receipt.canonicalReceipts)
309			if (sha256(await readFile(join(root, bound.path))) !== bound.sha256)
310				throw new Error(`factoriolab bound build receipt bytes drifted: ${bound.path}`);
311		if (
312			(await readFile(join(output, 'receipt.md'), 'utf8')) !==
313			renderWitnessAngularFactoriolabReceipt(receipt)
314		)
315			throw new Error('factoriolab human Witness receipt differs');
316		const serialized = canonicalize(receipt);
317		if (serialized.includes(root) || serialized.includes(process.env.USER ?? ''))
318			throw new Error('factoriolab receipt leaks host identity');
319		return receipt;
320	}
