322	export async function main(args = process.argv.slice(2)): Promise<void> {
323		const publishIndex = args.indexOf('--publish');
324		const verifyIndex = args.indexOf('--verify');
325		if (args.includes('--run-twice') && publishIndex >= 0 && args[publishIndex + 1]) {
326			const output = resolve(root, args[publishIndex + 1]!);
327			if (output !== witnessEvidence) throw new Error('factoriolab publish path differs');
328			const receipt = await runWitnessAngularFactoriolab();
329			process.stdout.write(
330				`${canonicalize({ result: receipt.result, digest: receipt.integrity.canonicalDigest })}\n`,
331			);
332			return;
333		}
334		if (verifyIndex >= 0 && args[verifyIndex + 1]) {
335			const receipt = await verifyWitnessAngularFactoriolab(resolve(root, args[verifyIndex + 1]!));
336			process.stdout.write(
337				`${canonicalize({ result: receipt.result, digest: receipt.integrity.canonicalDigest })}\n`,
338			);
339			return;
340		}
341		throw new Error(
342			'factoriolab Witness runner requires --run-twice --publish <dir> or --verify <dir>',
343		);
344	}
345	
346	if (basename(process.argv[1] ?? '') === 'angular-factoriolab-run.ts')
347		main().catch((error: unknown) => {
348			process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
349			process.exitCode = 1;
350		});
