type PageEventExpectation = {
  /** Minimum number of observed events (default 1). */atLeast?: number;
  /**
   * Only count events whose JSON-serialized detail contains this substring.
   * The settle-point pattern when a framework fires the same event name for
   * unrelated reasons (for example qwik's qsymbol for HMR re-renders versus
   * for a clicked handler's QRL).
   */
  detailIncludes?: string;
};
/**
 * Declarative check against the recorded page evidence, mirroring the
 * receipt's page record. Numeric fields are exact counts; omitted fields are
 * not checked.
 */
type PageOutcomeExpectation = {
  /** Exact number of main-frame navigations after the initial load (0 = never reloaded). */navigations?: number; /** Exact number of console errors plus uncaught page errors. */
  consoleErrors?: number; /** Exact number of failed network requests. */
  failedRequests?: number; /** Exact recorded interaction counts per verb. Omitted kinds are not checked. */
  interactions?: Partial<Record<PageInteraction['kind'], number>>; /** Tracked DOM events that must have fired. Requires `page.trackEvents(name)` first. */
  events?: Record<string, PageEventExpectation>;
};
type ArtifactTextExpectation = {
  /** Fragment(s) the artifact text must contain. */contains?: string | string[]; /** Fragment(s) the artifact text must not contain. */
  notContains?: string | string[];
};
/** Scope options for `expect.build.forbids`. */
type BuildForbidsOptions = {
  /**
   * Glob (relative to the runner root) selecting which emitted artifacts to
   * scan. Defaults to every text-like artifact the build emitted.
   */
  files?: string;
};
type ArtifactJsonPredicate = (json: unknown) => boolean | Promise<boolean>;
/** What `expect.page.bodyText` checks against the page body text. */
type BodyTextExpectation = {
  contains?: string;
  notContains?: string;
};
type PageExpectApi = {
  /** Waits until the selector's trimmed text equals the expected string. */text(page: PageHandle, selector: string, expected: string, options?: ExpectWaitOptions): Promise<void>; /** Waits until the page body text contains / no longer contains fragments. */
  bodyText(page: PageHandle, expectation: BodyTextExpectation, options?: ExpectWaitOptions): Promise<void>;
  /**
   * Waits until the selector's element carries the attribute. With a string
   * `expected`, waits until the attribute equals that value; with `null`,
   * waits until the element exists without the attribute (absence).
   */
  attribute(page: PageHandle, selector: string, attributeName: string, expected?: string | null, options?: ExpectWaitOptions): Promise<void>; /** Waits until the selector matches an element in the DOM. */
  exists(page: PageHandle, selector: string, options?: ExpectWaitOptions): Promise<void>; /** Waits until the selector matches exactly the expected number of elements. */
  count(page: PageHandle, selector: string, expected: number, options?: ExpectWaitOptions): Promise<void>; /** Waits until the selector matches a visible element. */
  visible(page: PageHandle, selector: string, options?: ExpectWaitOptions): Promise<void>; /** Waits until every given computed style property matches. */
  computedStyle(page: PageHandle, selector: string, styles: Record<string, string>, options?: ExpectWaitOptions): Promise<void>;
  /**
   * Declaratively checks the recorded page evidence (navigations, console
   * errors, failed requests, tracked events) and reports every mismatch at
   * once. Event expectations wait (bounded) for their counts; the numeric
   * checks compare what the page record holds at that point.
   */
  outcome(page: PageHandle, expectation: PageOutcomeExpectation, options?: ExpectWaitOptions): Promise<void>;
  /**
   * Shortcut for the common healthy-page check: no post-load navigations,
   * no console/page errors, and no failed requests.
   */
  clean(page: PageHandle, options?: ExpectWaitOptions): Promise<void>;
};
/** What `expect.response.matches` checks against an environment response. */
type ResponseExpectation = {
  status?: number;
  ok?: boolean; /** Substring match against the lowercased content-type header. */
  contentType?: string; /** Substring match against the response body. */
  contains?: string;
};
type ExpectApi = {
  /**
